// Anti-aliased bitmap fonts (8-bit coverage), generated by tools/fontgen from Inter SemiBold.
#pragma once

#include <cstdint>

namespace deck_ui {

struct Glyph {
    uint32_t offset;  // into Font::bitmap
    uint8_t w, h;
    int8_t x, y;      // top-left of the bitmap relative to the pen position at the top of the line
    uint8_t advance;
};

struct Font {
    int ascent, descent;
    int first, last;  // character codes covered
    const Glyph* glyphs;
    const uint8_t* bitmap;

    int line_height() const { return ascent + descent; }
    const Glyph* glyph(char c) const {
        const int code = static_cast<unsigned char>(c);
        return (code < first || code > last) ? nullptr : &glyphs[code - first];
    }
};

extern const Font kSmallFont;   // 11 px: labels
extern const Font kMediumFont;  // 14 px: values
extern const Font kLargeFont;   // 20 px: big words ("DHCP")

}  // namespace deck_ui
